import { Icon } from "@/components/ui/icon"
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"

export function BrandTile({ icon, small = false, className }: { icon: string; small?: boolean; className?: string }) {
  return (
    <span
      data-slot="brand-tile"
      className={cn(
        "grid shrink-0 place-items-center bg-marker/80 text-ink [border-radius:3px_8px_4px_9px/8px_3px_9px_4px]",
        small ? "size-5" : "size-8",
        className
      )}
    >
      <Icon name={icon} size={small ? 12 : 16} />
    </span>
  )
}

export function BrandText({ title, subtitle }: { title: string; subtitle?: string }) {
  return (
    <span className="grid flex-1 text-start text-sm leading-tight group-data-[collapsible=icon]:hidden">
      <span className="truncate font-bold">{title}</span>
      {" "}
      {subtitle ? <span className="truncate text-sm text-muted-foreground">{subtitle}</span> : null}
    </span>
  )
}

export function SidebarBrand({
  title,
  subtitle,
  icon,
  href = "#home",
  className,
}: {
  title: string
  subtitle?: string
  icon: string
  href?: string
  className?: string
}) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton size="lg" asChild className={className}>
          <a href={href}>
            <BrandTile icon={icon} />
            <BrandText title={title} subtitle={subtitle} />
          </a>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  )
}

"use client"

import * as React from "react"

import type { CalendarGroup } from "@/components/blocks/sidebar-shared/sidebar-data"
import { Calendar } from "@/components/ui/calendar"
import { Collapsible, CollapsibleContent, CollapsibleIndicator, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Icon } from "@/components/ui/icon"
import {
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarSeparator,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"

export function DatePicker({ selected, onSelect, defaultMonth }: { selected?: Date; onSelect?: (date: Date | undefined) => void; defaultMonth?: Date }) {
  return (
    <SidebarGroup className="px-0">
      <SidebarGroupContent>
        <Calendar
          mode="single"
          required={false}
          selected={selected}
          onSelect={onSelect}
          defaultMonth={defaultMonth ?? selected}
          className="mx-auto p-0 [--cell:2rem] compact:[--cell:1.875rem]"
        />
      </SidebarGroupContent>
    </SidebarGroup>
  )
}

export function Calendars({ groups, value, onValueChange }: { groups: CalendarGroup[]; value: string[]; onValueChange: (next: string[]) => void }) {
  const toggle = (name: string) => onValueChange(value.includes(name) ? value.filter((v) => v !== name) : [...value, name])

  return (
    <>
      {groups.map((group, index) => (
        <React.Fragment key={group.name}>
          <SidebarGroup className="py-0">
            <Collapsible defaultOpen={index === 0}>
              <SidebarGroupLabel asChild className="w-full text-sm text-sidebar-foreground hover:ll-swipe focus-visible:ll-swipe">
                <CollapsibleTrigger>
                  {group.name}
                  <CollapsibleIndicator className="ms-auto" />
                </CollapsibleTrigger>
              </SidebarGroupLabel>
              <CollapsibleContent>
                <SidebarGroupContent>
                  <SidebarMenu>
                    {group.items.map((item) => {
                      const on = value.includes(item.name)
                      return (
                        <SidebarMenuItem key={item.name}>
                          <SidebarMenuButton role="checkbox" aria-checked={on} onClick={() => toggle(item.name)}>
                            <Icon name={on ? "square-check" : "square"} className={cn(item.tone, !on && "opacity-70")} />
                            <span>{item.name}</span>
                          </SidebarMenuButton>
                        </SidebarMenuItem>
                      )
                    })}
                  </SidebarMenu>
                </SidebarGroupContent>
              </CollapsibleContent>
            </Collapsible>
          </SidebarGroup>
          <SidebarSeparator className="mx-0" />
        </React.Fragment>
      ))}
    </>
  )
}

export function containedClasses(contained: boolean) {
  return {
    provider: contained ? "h-full min-h-0" : undefined,
    sidebar: contained ? "h-full" : undefined,
    inset: contained ? "overflow-y-auto" : undefined,
  }
}

"use client"

import * as React from "react"

import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage, BreadcrumbSeparator } from "@/components/ui/breadcrumb"
import { Empty, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty"
import { Handwritten } from "@/components/ui/handwritten"
import type { MascotPose } from "@/components/ui/mascot"
import { Separator } from "@/components/ui/separator"
import { SidebarInset, SidebarTrigger } from "@/components/ui/sidebar"
import { InkTiles } from "@/lib/ink/react"
import { cn } from "@/lib/utils"

const SHEET = "ll-paper ll-stock-paper ll-tooth-cold"
const SHEET_TILES = ["fibre", "relief", "cloud"] as const
const STRIP = `${SHEET} [--ll-sheet-shadow:var(--ll-shadow-hair)]`

export function PageSheet({ className, children, ...props }: React.ComponentProps<typeof SidebarInset>) {
  return (
    <SidebarInset
      className={cn(
        SHEET,
        "before:block min-w-0 md:peer-data-[variant=floating]:m-2 md:peer-data-[variant=floating]:ms-0 md:peer-data-[variant=floating]:peer-data-[state=collapsed]:ms-2",
        className
      )}
      {...props}
    >
      <InkTiles tiles={SHEET_TILES} />
      {children}
    </SidebarInset>
  )
}

export interface Crumb {
  label: string
  href?: string
}

export function PageHeader({
  crumbs,
  bordered = false,
  sticky = false,
  trigger = "start",
  className,
  children,
}: {
  crumbs: (string | Crumb)[]
  bordered?: boolean
  sticky?: boolean
  trigger?: "start" | "end" | false
  className?: string
  children?: React.ReactNode
}) {
  const items = crumbs.map((c) => (typeof c === "string" ? { label: c } : c))
  const last = items.length - 1
  return (
    <header data-slot="page-header" className={cn("flex h-16 shrink-0 items-center gap-2 px-4 compact:h-14 calm:h-12", (bordered || sticky) && "relative overflow-x-clip", sticky && cn("sticky top-0 z-10", STRIP), className)}>
      {trigger === "start" ? (
        <>
          <SidebarTrigger className="-ms-1" />
          <Separator orientation="vertical" className="me-2 data-[orientation=vertical]:h-4" />
        </>
      ) : null}
      <Breadcrumb className="min-w-0">
        <BreadcrumbList>
          {items.map((item, i) =>
            i === last ? (
              <BreadcrumbItem key={item.label} className="min-w-0">
                <BreadcrumbPage className="line-clamp-1">{item.label}</BreadcrumbPage>
              </BreadcrumbItem>
            ) : (
              <React.Fragment key={item.label}>
                <BreadcrumbItem className="hidden md:block">
                  <BreadcrumbLink href={item.href ?? `#${item.label.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`}>{item.label}</BreadcrumbLink>
                </BreadcrumbItem>
                <BreadcrumbSeparator className="hidden md:block" />
              </React.Fragment>
            )
          )}
        </BreadcrumbList>
      </Breadcrumb>
      {children ? <div className="ms-auto flex items-center gap-2">{children}</div> : null}
      {trigger === "end" ? <SidebarTrigger className="-me-1 ms-auto" /> : null}
      {bordered ? <Separator className="absolute inset-x-0 bottom-0 w-auto" /> : null}
    </header>
  )
}

export function PageBody({ title, kicker, className, children }: { title: string; kicker?: string; className?: string; children?: React.ReactNode }) {
  return (
    <div data-slot="page-body" className={cn("flex flex-1 flex-col gap-4 p-4 pt-2 md:px-8", className)}>
      <div>
        {kicker ? <p className="font-type text-sm tracking-wide text-ink-muted">{kicker}</p> : null}
        <h1 className="font-script text-3xl leading-tight font-semibold">{title}</h1>
      </div>
      {children}
    </div>
  )
}

export function PageNote({
  title,
  pose,
  doodle,
  className,
  children,
}: {
  title: string
  pose?: MascotPose
  doodle?: string
  className?: string
  children?: React.ReactNode
}) {
  return (
    <div data-slot="page-note" className={cn("flex flex-1 items-center justify-center", className)}>
      <Empty className="max-w-sm p-4 md:p-6">
        <EmptyHeader>
          {pose || doodle ? <EmptyMedia pose={pose} doodle={doodle} size={72} /> : null}
          <EmptyTitle className="text-2xl">{title}</EmptyTitle>
          {children ? (
            <EmptyDescription>
              <Handwritten as="span">{children}</Handwritten>
            </EmptyDescription>
          ) : null}
        </EmptyHeader>
      </Empty>
    </div>
  )
}

"use client"

import * as React from "react"

import { Icon } from "@/components/ui/icon"
import { Label } from "@/components/ui/label"
import { SidebarGroup, SidebarGroupContent, SidebarInput } from "@/components/ui/sidebar"

type SearchFormProps = Omit<React.ComponentProps<"form">, "children"> & {
  placeholder?: string
  label?: string
  variant?: "sidebar" | "bar"
}

export function SearchForm({ placeholder = "Search the guide...", label = "Search", variant = "sidebar", className, onSubmit, ...props }: SearchFormProps) {
  const id = React.useId()
  const box = (
    <>
      <Label htmlFor={id} className="sr-only">
        {label}
      </Label>
      <SidebarInput id={id} type="search" placeholder={placeholder} className={variant === "bar" ? "h-8 ps-7" : "ps-8"} />
      <Icon name="search" className="pointer-events-none absolute start-2 top-1/2 -translate-y-1/2 opacity-60 select-none" />
    </>
  )

  return (
    <form
      role="search"
      className={className}
      onSubmit={(event) => {
        onSubmit?.(event)
        if (!onSubmit) event.preventDefault()
      }}
      {...props}
    >
      {variant === "bar" ? (
        <div className="relative">{box}</div>
      ) : (
        <SidebarGroup className="py-0">
          <SidebarGroupContent className="relative">{box}</SidebarGroupContent>
        </SidebarGroup>
      )}
    </form>
  )
}
